          "code": "import numpy as np\n\ndef expected_business_cost(y_true: np.ndarray, prob_pos: np.ndarray,\n                           threshold: float, cost_fp: float, cost_fn: float) -> dict:\n    \"\"\"Menghitung kerugian finansial ekspektasi dan metrik operasional pada ambang tau.\"\"\"\n    y_pred = (prob_pos >= threshold).astype(int)\n    tp = int(np.sum((y_pred == 1) & (y_true == 1)))\n    fp = int(np.sum((y_pred == 1) & (y_true == 0)))\n    fn = int(np.sum((y_pred == 0) & (y_true == 1)))\n    tn = int(np.sum((y_pred == 0) & (y_true == 0)))\n    total_cost = fp * cost_fp + fn * cost_fn\n    accuracy = (tp + tn) / len(y_true)\n    recall = tp / max(tp + fn, 1)\n    return {\"tau\": round(threshold, 3), \"tp\": tp, \"fp\": fp, \"fn\": fn,\n            \"accuracy\": round(accuracy, 4), \"recall\": round(recall, 4),\n            \"total_cost_usd\": round(total_cost, 2)}\n\nrng = np.random.default_rng(42)\nn_neg, n_pos = 1960, 40  # Prevalensi fraud 2% (sangat timpang)\ny_true = np.concatenate([np.zeros(n_neg, dtype=int), np.ones(n_pos, dtype=int)])\np_neg = rng.beta(1.2, 18.0, size=n_neg)\np_pos = rng.beta(3.2, 2.8, size=n_pos)\nprobs = np.concatenate([p_neg, p_pos])\n\ncost_fp, cost_fn = 15.0, 485.0\ntau_elkan = cost_fp / (cost_fp + cost_fn)  # Teorema Elkan (2001): 15 / 500 = 0.03\n\nres_naive = expected_business_cost(y_true, probs, threshold=0.50, cost_fp=cost_fp, cost_fn=cost_fn)\nres_elkan = expected_business_cost(y_true, probs, threshold=tau_elkan, cost_fp=cost_fp, cost_fn=cost_fn)\n\n# Sweep empiris untuk memverifikasi optimalitas tau_elkan\ntaus = np.linspace(0.01, 0.90, 90)\ncosts = [expected_business_cost(y_true, probs, float(t), cost_fp, cost_fn)[\"total_cost_usd\"] for t in taus]\nbest_idx = int(np.argmin(costs))\n\nprint(f\"Teorema Elkan tau* teoretis : {tau_elkan:.4f}\")\nprint(f\"Threshold 0.50 (Default)    : Acc={res_naive['accuracy']:.4f} | Recall={res_naive['recall']:.4f} | Cost=${res_naive['total_cost_usd']:,.2f}\")\nprint(f\"Threshold Elkan ({tau_elkan:.2f})      : Acc={res_elkan['accuracy']:.4f} | Recall={res_elkan['recall']:.4f} | Cost=${res_elkan['total_cost_usd']:,.2f}\")\nprint(f\"Threshold Empiris Terbaik   : tau={taus[best_idx]:.3f} | Min Cost=${costs[best_idx]:,.2f}\")\nprint(f\"Penghematan Finansial       : ${res_naive['total_cost_usd'] - res_elkan['total_cost_usd']:,.2f} per 2.000 transaksi\")",
