          "code": "import numpy as np\nfrom sklearn.datasets import make_classification\nfrom sklearn.ensemble import HistGradientBoostingClassifier\nfrom sklearn.metrics import make_scorer, precision_score, recall_score\nfrom sklearn.model_selection import TunedThresholdClassifierCV, train_test_split\n\nX, y = make_classification(\n    n_samples=1600, n_features=12, n_informative=6, n_redundant=2,\n    weights=[0.95, 0.05], flip_y=0.01, random_state=42\n)\nX_train, X_test, y_train, y_test = train_test_split(\n    X, y, test_size=0.25, stratify=y, random_state=42\n)\n\nCOST_FP, COST_FN = 15.0, 485.0\n\ndef neg_business_cost(y_true, y_pred):\n    fp = np.sum((y_pred == 1) & (y_true == 0))\n    fn = np.sum((y_pred == 0) & (y_true == 1))\n    return -float(fp * COST_FP + fn * COST_FN)\n\ncost_scorer = make_scorer(neg_business_cost)\n\nbase_model = HistGradientBoostingClassifier(max_iter=60, max_depth=4, learning_rate=0.08, random_state=42)\nbase_model.fit(X_train, y_train)\npred_default = base_model.predict(X_test)\n\n# Scikit-Learn modern: TunedThresholdClassifierCV mengoptimasi threshold di dalam CV tanpa leakage\ntuned_model = TunedThresholdClassifierCV(\n    estimator=HistGradientBoostingClassifier(max_iter=60, max_depth=4, learning_rate=0.08, random_state=42),\n    scoring=cost_scorer,\n    cv=3,\n    thresholds=40,\n    random_state=42,\n)\ntuned_model.fit(X_train, y_train)\npred_tuned = tuned_model.predict(X_test)\n\ncost_def = -neg_business_cost(y_test, pred_default)\ncost_tun = -neg_business_cost(y_test, pred_tuned)\nprint(f\"Default tau=0.50 -> Precision={precision_score(y_test, pred_default):.3f}, Recall={recall_score(y_test, pred_default):.3f}, Cost=${cost_def:,.2f}\")\nprint(f\"Tuned tau={tuned_model.best_threshold_:.3f} -> Precision={precision_score(y_test, pred_tuned):.3f}, Recall={recall_score(y_test, pred_tuned):.3f}, Cost=${cost_tun:,.2f}\")\nprint(f\"Penurunan Kerugian Uji: ${cost_def - cost_tun:,.2f} ({(cost_def - cost_tun) / cost_def * 100:.1f}%)\")",
