          "code": "import numpy as np\nfrom sklearn.datasets import make_classification\nfrom sklearn.feature_selection import SelectKBest, f_classif\nfrom sklearn.linear_model import LogisticRegression\nfrom sklearn.model_selection import cross_val_score\nfrom sklearn.pipeline import Pipeline\n\n# Demonstrasi kuantitatif Data Leakage: data target acak murni (true Bayes accuracy = 50%)\nrng = np.random.default_rng(42)\nX_noise = rng.normal(0, 1, size=(120, 2000))\ny_random = rng.integers(0, 2, size=120)\n\n# SALAH: SelectKBest dijalankan SEBELUM cross-validation (bocor label uji!)\nX_leaked = SelectKBest(f_classif, k=15).fit_transform(X_noise, y_random)\nleaked_acc = cross_val_score(LogisticRegression(max_iter=500), X_leaked, y_random, cv=5).mean()\n\n# BENAR: SelectKBest diisolasi DI DALAM Pipeline (fit per lipatan latih saja)\nsafe_pipe = Pipeline([\n    (\"select\", SelectKBest(f_classif, k=15)),\n    (\"clf\", LogisticRegression(max_iter=500)),\n])\nhonest_acc = cross_val_score(safe_pipe, X_noise, y_random, cv=5).mean()\n\nprint(f\"True Signal Accuracy (Data Noise Murni) : 50.00%\")\nprint(f\"Skor CV Bocor (SelectKBest di luar CV)  : {leaked_acc*100:.2f}%  <-- ILUSI!\")\nprint(f\"Skor CV Jujur (SelectKBest di Pipeline) : {honest_acc*100:.2f}%  <-- AKURAT\")",
