          "code": "import numpy as np\n\ndef audit_design_matrix(X: np.ndarray, feature_names: list) -> dict:\n    \"\"\"Audit aljabar matriks desain: rank numerik, condition number SVD, dan VIF tiap fitur.\"\"\"\n    Xc = X - np.mean(X, axis=0)\n    s = np.linalg.svd(Xc, compute_uv=False)\n    tol = max(Xc.shape) * np.finfo(float).eps * s[0]\n    rank = int(np.sum(s > tol))\n    cond = float(s[0] / s[-1]) if s[-1] > 1e-15 else float(\"inf\")\n\n    # VIF via diagonal invers matriks korelasi (dengan pengaman pinv untuk singular)\n    corr = np.corrcoef(Xc, rowvar=False)\n    vifs = np.diag(np.linalg.pinv(corr))\n    vif_map = {name: round(float(v), 2) for name, v in zip(feature_names, vifs)}\n    return {\"shape\": X.shape, \"rank\": rank, \"full_rank\": rank == X.shape[1],\n            \"condition_number\": round(cond, 2), \"vif\": vif_map}\n\nrng = np.random.default_rng(42)\nn = 500\nincome = rng.normal(60_000, 12_000, size=n)\ndebt = rng.normal(18_000, 5_000, size=n)\n# Near-collinear duplicate: total_liability hampir identik dengan debt + noise kecil\ntotal_liability = debt * 1.02 + rng.normal(0, 120, size=n)\nage = rng.normal(38, 9, size=n)\n\nX_design = np.column_stack([income, debt, total_liability, age])\nreport = audit_design_matrix(X_design, [\"income\", \"debt\", \"total_liability\", \"age\"])\nprint(f\"Shape: {report['shape']} | Rank: {report['rank']}/{report['shape'][1]} | Full Rank: {report['full_rank']}\")\nprint(f\"Condition Number kappa(X): {report['condition_number']:,.2f}\")\nprint(\"VIF per Fitur:\", report[\"vif\"])",
